package org.demo.orderservice.privacy;

import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
import static org.demo.platformsecurity.privacy.CommerceRetentionAssessment.*;
import static org.demo.orderservice.privacy.CommerceRetentionHolds.Reason.*;

@Testcontainers
class CommerceRetentionHoldsPostgresIT {
    @Container static final PostgreSQLContainer<?> DB=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("retention_holds").withUsername("fixture").withPassword("fixture-only");
    static DriverManagerDataSource ds;static JdbcTemplate jdbc;static DataSourceTransactionManager manager;
    CommerceRetentionJobs jobs;CommerceRetentionHolds holds;
    @BeforeAll static void setup(){ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());jdbc=new JdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();}
    @BeforeEach void reset(){jdbc.execute("TRUNCATE commerce_retention_holds,commerce_retention_hold_scopes,orders,commerce_retention_jobs,commerce_retention_evidence,commerce_retention_bindings,commerce_retention_payment_evidence,commerce_retention_order_state RESTART IDENTITY CASCADE");jobs=new CommerceRetentionJobs(ds,manager);holds=new CommerceRetentionHolds(ds,manager);seed(10,17L);seed(11,17L);seed(12,18L);seed(13,null);}
    void seed(long id,Long customer){jdbc.update("INSERT INTO orders(id,customer_id,customer_email,total_price,status,delivery_first_name,delivery_last_name,delivery_street,delivery_postal_code,delivery_city,delivery_country,delivery_phone,delivery_method,delivery_cost,discount_amount,fulfillment_type,idempotency_key,checkout_request_hash,checkout_principal,created_at,updated_at) VALUES(?,?,'fixture@example.test',10,'CANCELLED','Fixture','Buyer','Street','00-001','City','PL','123','COURIER',0,0,'HOME_DELIVERY',?,?,'fixture',now(),now())",id,customer,"fixture-"+id,"a".repeat(64));jdbc.update("INSERT INTO order_items(order_id,product_id,product_name,sku,quantity,unit_price,total_price) VALUES(?,1,'Fixture','FIX',1,10,10)",id);jdbc.update("INSERT INTO order_sagas(order_id,state,created_at,updated_at) VALUES(?,'FAILED',now(),now())",id);}
    Subject full(long order,Phase phase){var s=jobs.prepare(order,phase);var reconciled=Instant.now().minus(400,ChronoUnit.DAYS).truncatedTo(ChronoUnit.MICROS);var redacted=phase==Phase.MINIMUM_REMOVAL?Instant.now().minus(100,ChronoUnit.DAYS).truncatedTo(ChronoUnit.MICROS):null;for(var p:Participant.values())jobs.record(new ChainProof(p,s,phase,POLICY,State.CONFIRMED,reconciled,redacted));for(var g:requiredGuards(phase))if(g==Guard.FIELD_SCOPE_REVIEWED)jobs.recordReviewedFieldScope(s,phase,org.demo.platformsecurity.privacy.CommerceRetentionFieldScope.verifiedDigest());else jobs.record(g,new GuardProof(s,phase,POLICY,g==Guard.PRESERVATION_POLICY_REVIEWED||g==Guard.INDEPENDENT_JOURNAL_CURRENT?State.UNKNOWN:State.CONFIRMED));return s;}
    Result assess(){jdbc.update("UPDATE commerce_retention_jobs SET next_attempt_at=clock_timestamp()-interval '10 seconds' WHERE state IN ('WAITING_PROOF','WAITING_AGE')");return jobs.assess(jobs.claim().orElseThrow()).orElseThrow();}
    long count(String table){return jdbc.queryForObject("SELECT count(*) FROM "+table,Long.class);}
    @Test void emptyRegistryDoesNotCreatePositiveGuardEvidence(){var s=jobs.prepare(10,Phase.REDACTION);var time=Instant.now().minus(400,ChronoUnit.DAYS).truncatedTo(ChronoUnit.MICROS);for(var p:Participant.values())jobs.record(new ChainProof(p,s,Phase.REDACTION,POLICY,State.CONFIRMED,time,null));assertThat(assess().code()).isEqualTo(Code.MISSING_GUARD_PROOF);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce_retention_evidence WHERE kind='GUARD'",Long.class)).isZero();}
    @Test void knownHoldBlocksEvenWithMissingBusinessProofs(){holds.placeOrder(10,UUID.randomUUID(),Guard.NO_PRESERVATION_HOLD,PRESERVATION_REQUEST);jobs.prepare(10,Phase.REDACTION);var result=assess();assertThat(result.outcome()).isEqualTo(Outcome.BLOCKED);assertThat(result.activationAllowed()).isFalse();assertThat(count("commerce_retention_evidence")).isZero();}
    @Test void oldPositiveGuardCannotOverrideAKnownOrderHold(){var s=full(10,Phase.REDACTION);holds.placeOrder(10,UUID.randomUUID(),Guard.NO_PRESERVATION_HOLD,PRESERVATION_REQUEST);assertThat(jdbc.queryForObject("SELECT current FROM commerce_retention_jobs WHERE generation=?",Boolean.class,s.chainGeneration())).isFalse();var next=full(10,Phase.REDACTION);assertThat(next.chainGeneration()).isNotEqualTo(s.chainGeneration());assertThat(assess().code()).isEqualTo(Code.PRESERVATION_OR_DEPENDENCY_BLOCK);assertThat(count("orders")).isEqualTo(4);}
    @Test void customerHoldRequeuesOnlyAffectedPurchasesWithoutFanoutMutation(){for(long id:new long[]{10,11,12,13}){full(id,Phase.REDACTION);assertThat(assess().outcome()).isEqualTo(Outcome.WAIT);}jdbc.update("UPDATE commerce_retention_jobs SET next_attempt_at=clock_timestamp()+interval '1 day'");holds.placeCustomerPurchases(17,UUID.randomUUID(),Guard.NO_OPEN_OR_REOPENED_CASE,OPEN_CASE);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce_retention_jobs WHERE state='WAITING_PROOF'",Long.class)).isEqualTo(4);for(int n=0;n<2;n++){var w=jobs.claim().orElseThrow();assertThat(w.subject().customerId()).isEqualTo(17);assertThat(jobs.assess(w).orElseThrow().outcome()).isEqualTo(Outcome.BLOCKED);}assertThat(jobs.claim()).isEmpty();assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce_retention_jobs WHERE state='WAITING_PROOF' AND (customer_id=18 OR customer_id IS NULL)",Long.class)).isEqualTo(2);}
    @Test void repeatedRequestIsIdempotentAndCannotRetireANewGeneration(){UUID request=UUID.randomUUID();var id=holds.placeOrder(10,request,Guard.NO_OPEN_OR_REOPENED_CASE,OPEN_CASE);var s=jobs.prepare(10,Phase.REDACTION);assertThat(holds.placeOrder(10,request,Guard.NO_OPEN_OR_REOPENED_CASE,OPEN_CASE)).isEqualTo(id);assertThat(jdbc.queryForObject("SELECT revision FROM commerce_retention_hold_scopes WHERE scope_type='ORDER' AND subject_id=10",Long.class)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT current FROM commerce_retention_jobs WHERE generation=?",Boolean.class,s.chainGeneration())).isTrue();assertThatThrownBy(()->holds.placeCustomerPurchases(17,request,Guard.NO_OPEN_OR_REOPENED_CASE,OPEN_CASE)).hasMessage("RETENTION_HOLD_REQUEST_CONFLICT");assertThat(count("commerce_retention_holds")).isEqualTo(1);}
    @Test void orderHoldRetiresAnAlreadyClaimedLease(){full(10,Phase.REDACTION);jdbc.update("UPDATE commerce_retention_jobs SET next_attempt_at=clock_timestamp()-interval '1 second'");var w=jobs.claim().orElseThrow();holds.placeOrder(10,UUID.randomUUID(),Guard.NO_ACTIVE_RETRY_OR_DLQ,DEPENDENCY_REVIEW);assertThat(jobs.assess(w)).isEmpty();assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce_retention_jobs WHERE run_token IS NOT NULL OR run_until IS NOT NULL",Long.class)).isZero();}
    @Test void minimumDependenciesDoNotBecomeAnUnrelatedRedactionHold(){holds.placeOrder(10,UUID.randomUUID(),Guard.FINANCIAL_DEPENDENCIES_RELEASED,DEPENDENCY_REVIEW);var s=full(10,Phase.REDACTION);assertThat(assess().outcome()).isEqualTo(Outcome.WAIT);jobs.invalidate(10,s.chainGeneration());full(10,Phase.MINIMUM_REMOVAL);assertThat(assess().outcome()).isEqualTo(Outcome.BLOCKED);}
    @Test void rollbackRestoresHoldRevisionAndJobStateAtomically(){var s=full(10,Phase.REDACTION);assertThat(assess().outcome()).isEqualTo(Outcome.WAIT);new TransactionTemplate(manager).executeWithoutResult(tx->{holds.placeOrder(10,UUID.randomUUID(),Guard.NO_PRESERVATION_HOLD,PRESERVATION_REQUEST);assertThat(count("commerce_retention_holds")).isEqualTo(1);tx.setRollbackOnly();});assertThat(count("commerce_retention_holds")).isZero();assertThat(jdbc.queryForObject("SELECT current FROM commerce_retention_jobs WHERE generation=?",Boolean.class,s.chainGeneration())).isTrue();assertThat(jdbc.queryForObject("SELECT revision FROM commerce_retention_hold_scopes WHERE scope_type='ORDER' AND subject_id=10",Long.class)).isZero();}
    @Test void historyCannotBeRewrittenDeletedOrReleased(){holds.placeOrder(10,UUID.randomUUID(),Guard.NO_PRESERVATION_HOLD,PRESERVATION_REQUEST);for(String sql:List.of("DELETE FROM commerce_retention_holds","UPDATE commerce_retention_holds SET guard='NO_ACTIVE_RETRY_OR_DLQ'","DELETE FROM commerce_retention_hold_scopes","UPDATE commerce_retention_hold_scopes SET revision=999"))assertThatThrownBy(()->jdbc.update(sql)).isInstanceOf(org.springframework.dao.DataAccessException.class);jdbc.update("UPDATE commerce_retention_hold_scopes SET restore_blocked=TRUE");assertThat(jdbc.queryForObject("SELECT revision FROM commerce_retention_hold_scopes",Long.class)).isEqualTo(2);assertThatThrownBy(()->jdbc.update("UPDATE commerce_retention_hold_scopes SET restore_blocked=FALSE")).isInstanceOf(org.springframework.dao.DataAccessException.class);}
    @Test void restoreQuarantineBlocksPreparationAndAssessment(){full(10,Phase.REDACTION);assertThat(assess().outcome()).isEqualTo(Outcome.WAIT);jdbc.update("UPDATE commerce_retention_hold_scopes SET restore_blocked=TRUE");assertThatThrownBy(()->jobs.prepare(10,Phase.REDACTION)).hasMessage("RETENTION_HOLD_QUARANTINED");assertThat(jobs.assess(jobs.claim().orElseThrow()).orElseThrow().outcome()).isEqualTo(Outcome.BLOCKED);assertThat(jobs.claim()).as("unchanged quarantine does not spin on a blocked assessment").isEmpty();}
    @Test void unknownTargetsAndNonHoldGuardsCannotCreateMetadata(){for(var attempt:List.<Runnable>of(()->holds.placeOrder(999,UUID.randomUUID(),Guard.NO_PRESERVATION_HOLD,PRESERVATION_REQUEST),()->holds.placeCustomerPurchases(999,UUID.randomUUID(),Guard.NO_PRESERVATION_HOLD,PRESERVATION_REQUEST),()->holds.placeOrder(10,UUID.randomUUID(),Guard.INDEPENDENT_JOURNAL_CURRENT,DEPENDENCY_REVIEW),()->holds.placeCustomerPurchases(0,UUID.randomUUID(),Guard.NO_PRESERVATION_HOLD,PRESERVATION_REQUEST)))assertThatThrownBy(attempt::run).isInstanceOf(IllegalArgumentException.class);assertThat(count("commerce_retention_holds")).isZero();assertThat(count("commerce_retention_hold_scopes")).isZero();}
    @Test void customerHoldSerializesWithAssessmentScopeSnapshot()throws Exception{
        jobs.prepare(10,Phase.REDACTION);var started=new CountDownLatch(1);
        try(var executor=Executors.newSingleThreadExecutor()){
            java.util.concurrent.atomic.AtomicReference<Future<UUID>> future=new java.util.concurrent.atomic.AtomicReference<>();
            new TransactionTemplate(manager).executeWithoutResult(tx->{jdbc.queryForList("SELECT id FROM orders WHERE id=10 FOR NO KEY UPDATE");assertThat(holds.snapshot(10,17,Phase.REDACTION).blockers()).isEmpty();future.set(executor.submit(()->{started.countDown();return holds.placeCustomerPurchases(17,UUID.randomUUID(),Guard.NO_OPEN_OR_REOPENED_CASE,OPEN_CASE);}));
                try{
                    assertThat(started.await(1,TimeUnit.SECONDS)).isTrue();long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(1);boolean waiting=false;
                    while(!waiting && System.nanoTime()<deadline){jdbc.execute("SELECT pg_stat_clear_snapshot()");waiting=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND wait_event_type='Lock' AND query LIKE '%commerce_retention_hold_scopes%')",Boolean.class));if(!waiting)Thread.sleep(20);}
                    assertThat(waiting).as("customer hold writer really waits on the scope row lock").isTrue();
                }catch(InterruptedException interrupted){throw new AssertionError(interrupted);}assertThat(future.get().isDone()).isFalse();});
            assertThat(future.get().get(5,TimeUnit.SECONDS)).isNotNull();
        }
        assertThat(assess().outcome()).isEqualTo(Outcome.BLOCKED);
    }
}
